package com.zoutiw.bibla.data

object LamentationsData {
    val verses: List<Verse> = listOf(
        Verse(book = "Lamantasyon", chapter = 1, verseNumber = 1, text = "Jan lavil Jerizalèm te plen moun yon lè! Gade, jounen jòdi a li chita pou kont li! Li tankou yon fanm ki pèdi mari l'. Tout nasyon sou latè te respekte pouvwa li. Li te devan tout lòt lavil yo. Koulye a, men li tounen esklav!", bookId = 25),
        Verse(book = "Lamantasyon", chapter = 1, verseNumber = 2, text = "Tout lannwit l'ap plede kriye, dlo ap koule nan je l' san rete. Nan tout moun ki te renmen l' yo, li pa jwenn yonn menm pou konsole l'. Tout zanmi l' yo trayi l', yo tout fè l' lènmi koulye a.", bookId = 25),
        Verse(book = "Lamantasyon", chapter = 1, verseNumber = 3, text = "Yo depòte moun peyi Jida yo, y'ap peze yo. Y'ap kraze yo anba travay di. Moun peyi Jida yo ap viv nan lòt peyi. Yo pa gen kote pou yo poze kò yo. Tout moun ki pa vle wè yo sènen yo toupatou! Pa gen chape pou yo.", bookId = 25),
        Verse(book = "Lamantasyon", chapter = 1, verseNumber = 4, text = "Chemen ki mennen sou mòn Siyon yo blanch! Pesonn pa moute al fè sèvis jou fèt yo. Pòtay li yo vid. Prèt yo ap plenn. Tout medam ki konn chante yo nan lafliksyon. Mòn Siyon an nan gwo chagren.", bookId = 25),
        Verse(book = "Lamantasyon", chapter = 1, verseNumber = 5, text = "Lènmi l' yo pran pye sou li. Moun ki pa vle wè l' yo gen lapè avè l'. Seyè a ap fè l' soufri pou tout kantite peche li fè yo. Ata timoun piti yo depòte. Lènmi pouse yo mache devan yo!", bookId = 25),
        Verse(book = "Lamantasyon", chapter = 1, verseNumber = 6, text = "Lavil Jerizalèm pèdi tout prestij li. Chèf li yo tankou kabrit mawon ki pa jwenn zèb pou yo manje. Yo pa gen fòs pou yo kouri chape dèvan moun ki dèyè yo.", bookId = 25),
        Verse(book = "Lamantasyon", chapter = 1, verseNumber = 7, text = "Nan mizè kote yo ye a, nan pwonmennen toupatou sa a, moun lavil Jerizalèm yo chonje tout bèl bagay yo te gen nan tan lontan. Lè moun li yo tonbe anba men lènmi pesonn pa vin pote yo sekou. Moun ki pa vle wè l' yo ap pale sou li. Yo kontan wè jan yo fini avè l'.", bookId = 25),
        Verse(book = "Lamantasyon", chapter = 1, verseNumber = 8, text = "Lavil Jerizalèm te fè anpil peche! Li bay moun degoutans. Moun ki te konn gen respè pou li yo, koulye a yo pa gade l' menm. Li kanpe tankou yon fanm toutouni devan yo. Li menm, l'ap plenn, l'ap kache figi l' tèlman li wont.", bookId = 25),
        Verse(book = "Lamantasyon", chapter = 1, verseNumber = 9, text = "Malpwòpte te sou tout rad li, men li pa t' fè lide kote sa t'ap mennen l'. Li tonbe plat atè. Pesonn pa vin konsole li. Bondye papa m', gade nan ki mizè mwen ye non! Lènmi m' yo mete pye sou kou mwen.", bookId = 25),
        Verse(book = "Lamantasyon", chapter = 1, verseNumber = 10, text = "Lènmi l' yo vòlò tout bèl bagay li te genyen. Moun Bondye te defann mete pye nan tanp lan, li wè yo antre ata kote yo mete apa pou Bondye a.", bookId = 25),
        Verse(book = "Lamantasyon", chapter = 1, verseNumber = 11, text = "Tout moun ap plenn, y'ap chache manje pou yo manje! Yo bay tout byen yo pou yo sa jwenn manje, pou yo pa fin mouri. -Granmèt o, voye je ou gade m' non! Wè jan y'ap pase m' nan betiz!", bookId = 25),
        Verse(book = "Lamantasyon", chapter = 1, verseNumber = 12, text = "Nou tout k'ap pase la a, gade non! Sa pa di nou anyen? Pesonn pa janm pase sa m'ap pase la a. Se Bondye, Seyè a, ki ankòlè k'ap manyen avè m'.", bookId = 25),
        Verse(book = "Lamantasyon", chapter = 1, verseNumber = 13, text = "Li rete anwo, li voye dife sou mwen, yon dife ki boule tout anndan mwen. Li tann pèlen pou mwen, li fè m' tonbe atè, Li kite m' pou kont mwen. San rete m'ap kòde anba soufrans.", bookId = 25),
        Verse(book = "Lamantasyon", chapter = 1, verseNumber = 14, text = "Li make tout peche m' yo. Li fè yon pakèt ak yo. Li pandye yo nan kou m'. Yo sitèlman lou, m' pa kapab ankò! Bondye sèl Mèt la lage m' nan men lènmi m' yo. M' pa ka kenbe tèt ak yo.", bookId = 25),
        Verse(book = "Lamantasyon", chapter = 1, verseNumber = 15, text = "Bondye sèl Mèt la kraze tout vanyan gason m' te genyen yo anba pye l'. Li sanble yon foul moun pou yo atake m', pou yo touye tout jenn gason m' yo. Li kraze moun peyi Jida yo tankou kann nan moulen.", bookId = 25),
        Verse(book = "Lamantasyon", chapter = 1, verseNumber = 16, text = "Se poutèt sa m'ap kriye konsa! Dlo ap ponpe nan je m' san rete. Pa gen pesonn pou konsole m', pesonn pou ban m' kouraj. Lènmi m' yo gen pye yo sou kou mwen. Moun mwen yo pa gen anyen ankò.", bookId = 25),
        Verse(book = "Lamantasyon", chapter = 1, verseNumber = 17, text = "Mòn Siyon an lonje men l', men, pa gen pesonn pou ba l' kouraj. Seyè a rele tout moun ki pa vle wè peyi Jakòb la, pou yo sènen l' toupatou. Lavil Jerizalèm tounen malpwòpte nan mitan yo.", bookId = 25),
        Verse(book = "Lamantasyon", chapter = 1, verseNumber = 18, text = "Men, Seyè a gen rezon l' nan pla men l' paske mwen te refize koute l' lè li t'ap pale m'! Nou tout moun ki toupatou, koute m'! Gade jan m'ap soufri! Yo depòte jenn gason ak jenn fi m' yo.", bookId = 25),
        Verse(book = "Lamantasyon", chapter = 1, verseNumber = 19, text = "Mwen rele zanmi m' yo. Men, yo pa okipe m' menm! Prèt yo ak chèf fanmi yo mouri nan lavil la pandan y'ap chache manje pou yo reprann fòs.", bookId = 25),
        Verse(book = "Lamantasyon", chapter = 1, verseNumber = 20, text = "Seyè, gade jan kè m' sere non! Mwen boulvèse. Kè m' ap fè m' mal paske mwen te fè wòklò. Nan lari y'ap ansasinen mwen. Anndan kay menm, se pa pale!", bookId = 25),
        Verse(book = "Lamantasyon", chapter = 1, verseNumber = 21, text = "Koute jan m'ap plenn. Pa gen pesonn pou ban m' kouraj. Lènmi m' yo vin konnen nan ki malè mwen ye. Yo kontan wè se ou menm ki fè m' sa. Tanpri, fè jou ou te pwomèt la rive non, pou lènmi m' yo ka vin jan mwen ye a.", bookId = 25),
        Verse(book = "Lamantasyon", chapter = 1, verseNumber = 22, text = "Jije yo pou mechanste yo. Pini yo menm jan ou pini m' pou peche m' yo. M'ap plenn anpil. Kè m' ap fann. Plenn", bookId = 25),
        Verse(book = "Lamantasyon", chapter = 2, verseNumber = 1, text = "Bondye sèl Mèt la fè kòlè, li voye yon gwo nwaj nwa kouvri lavil Jerizalèm. Tou sa ki te fè respè pèp Izrayèl la, li kraze l' anba pye l'. Jou li fè kòlè a, ata tanp kote li poze pye l' la, li pa chonje l'.", bookId = 25),
        Verse(book = "Lamantasyon", chapter = 2, verseNumber = 2, text = "Bondye sèl Mèt la te san pitye, li devaste dènye jaden moun fanmi Jakòb yo. Li fè yon sèl kòlè, li kraze tout fò ki te pwoteje peyi Jida a. Li trennen gouvènman an ansanm ak tout chèf yo nan labou. Li fè yo wont.", bookId = 25),
        Verse(book = "Lamantasyon", chapter = 2, verseNumber = 3, text = "Nan gwo kòlè li, li kraze tout fòs kouraj pèp Izrayèl la. Li derefize ede nou lè lènmi atake nou. Li move sou nou, li te tankou yon dife k'ap boule dènye bagay alawonn.", bookId = 25),
        Verse(book = "Lamantasyon", chapter = 2, verseNumber = 4, text = "Li atake nou, li tonbe sou nou tankou yon lènmi. Li touye tou sa ki te fè plezi ak kontantman nou. Jouk anndan lakay nou, li fè nou santi jan li move sou nou.", bookId = 25),
        Verse(book = "Lamantasyon", chapter = 2, verseNumber = 5, text = "Tankou yon lènmi, Bondye sèl Mèt la fini ak pèp Izrayèl la. Li kraze dènye gwo kay li yo, li detwi tout fò li yo. Li fè moun peyi Jida yo rete ap plenn sou plenn.", bookId = 25),
        Verse(book = "Lamantasyon", chapter = 2, verseNumber = 6, text = "Li fè tanp lan tounen tankou yon jaden vòlò devaste. Li kraze kote li konn gen randevou ak pèp la. Li fè sispann tout jou fèt, tout jou repo sou mòn Siyon an. Li move ata sou wa ak prèt yo. Yo tout pase anba men l'.", bookId = 25),
        Verse(book = "Lamantasyon", chapter = 2, verseNumber = 7, text = "Bondye sèl Mèt la voye lotèl li a jete. Li pa vle wè kay yo te mete apa pou li a. Li kite lènmi yo kraze miray gwo kay yo. Lènmi yo fè fèt, yo rele byen fò nan kay Seyè a tankou lè n'ap fè seremoni pou li.", bookId = 25),
        Verse(book = "Lamantasyon", chapter = 2, verseNumber = 8, text = "Seyè a, Bondye sèl Mèt la, te soti pou l' kraze miray lavil Siyon an. Li fè plan pou lè l' kraze l', li kraze l' nèt. Miray fò yo ak miray ranpa yo tonbe, yo kraze ansanm.", bookId = 25),
        Verse(book = "Lamantasyon", chapter = 2, verseNumber = 9, text = "Pòtay yo atè kouvri anba fatra. Ba pòtay yo kase, yo pa ka sèvi ankò. Yo depòte wa a ak chèf yo nan peyi etranje. Pa gen pesonn pou moutre sa ki nan lalwa. Menm pwofèt yo, Bondye pa pale ak yo nan vizyon ankò.", bookId = 25),
        Verse(book = "Lamantasyon", chapter = 2, verseNumber = 10, text = "Chèf fanmi lavil Jerizalèm yo chita atè, men nan machwè! Yo nan gwo lapenn, yo voye pousyè sou tèt yo, yo mete rad sak sou yo. Jenn fi yo menm rete tèt bese.", bookId = 25),
        Verse(book = "Lamantasyon", chapter = 2, verseNumber = 11, text = "Je m' wouj afòs mwen kriye. Kè m' sere. M' pèdi kouraj lè m' wè jan pèp mwen an ap fini, jan timoun yo ak ti bebe yo ap tonbe endispoze nan mitan lari kapital la.", bookId = 25),
        Verse(book = "Lamantasyon", chapter = 2, verseNumber = 12, text = "Y'ap rele manman yo, Y'ap kriye pou pen ak dlo sikre. Yo tonbe san konesans nan lari a tankou moun ki blese, yo mouri nan bra manman yo.", bookId = 25),
        Verse(book = "Lamantasyon", chapter = 2, verseNumber = 13, text = "Aa! Jerizalèm, kisa pou m' di ou la a! Ak ki moun pou m' ta konpare sò ou? Ki jan pou m' ankouraje ou? Pesonn pa janm soufri konsa. Malè ki tonbe sou ou a pa gen limit, li gwosè lanmè a! Pesonn pa ka fè anyen pou ou ankò!", bookId = 25),
        Verse(book = "Lamantasyon", chapter = 2, verseNumber = 14, text = "Pwofèt yo pa wè anyen pou yo di ou pase manti ak radòt. Yo kase fèy kouvri peche ou yo pou ou. Yo fè ou pèdi chans ou te gen pou ou te kanpe ankò a. Yo pa wè anyen pou yo di ou. Y'ap ba ou manti, y'ap pete ou.", bookId = 25),
        Verse(book = "Lamantasyon", chapter = 2, verseNumber = 15, text = "Tout moun sou granchemen an ap rele chalbari dèyè ou. Y'ap lonje dwèt sou ou, y'ap pase lavil Jerizalèm nan rizib. Y'ap ri, y'ap di: -Men lavil yo t'ap di pa gen pi bèl pase l' la wi! Se lavil sa a wi ki te fè kè tout moun bat pou li a!", bookId = 25),
        Verse(book = "Lamantasyon", chapter = 2, verseNumber = 16, text = "Tout lènmi ou yo ap pale ou mal byen fò. Y'ap rele chalbari dèyè ou. Y'ap lonje bouch yo sou ou. Y'ap di: -Nou fini avè l'! Men jou nou t'ap tann lan! Nou jwenn li jòdi a!", bookId = 25),
        Verse(book = "Lamantasyon", chapter = 2, verseNumber = 17, text = "Seyè a fè sa li te di li t'ap fè a. Li kenbe pawòl li te di depi nan tan lontan an. Li kraze san gade dèyè. Li fè lènmi nou yo genyen batay la sou nou. Li fè yo kontan wè jan nou fini.", bookId = 25),
        Verse(book = "Lamantasyon", chapter = 2, verseNumber = 18, text = "Jerizalèm, ou mèt kite miray ou yo rele nan pye Seyè a. Kite dlo koule nan je ou tankou larivyè, lajounen kou lannwit! Pa pran kanpo menm! Pa kite dlo nan je ou cheche!", bookId = 25),
        Verse(book = "Lamantasyon", chapter = 2, verseNumber = 19, text = "Leve nan mitan lannwit, chak fwa kòk chante, rele nan pye Bondye! Louvri kè ou bay Bondye sèl Mèt la. Mande l' gras mizèrikòd pou ti pitit ou yo, k'ap mouri grangou nan chak kalfou!", bookId = 25),
        Verse(book = "Lamantasyon", chapter = 2, verseNumber = 20, text = "Gade non, Seyè! Manyè wè ki moun w'ap matirize konsa! Manman ap manje pitit ki sot nan vant yo, pitit yo renmen anpil yo. Y'ap touye prèt yo ak pwofèt yo nan kote ki apa pou Bondye sèl Mèt la, nan tanp lan.", bookId = 25),
        Verse(book = "Lamantasyon", chapter = 2, verseNumber = 21, text = "Jenn gason kou granmoun mouri atè nan mitan lari. Jenn tifi yo ak jenn tigason yo mouri nan lagè! Jou ou fè kòlè a, ou touye moun, ou kraze moun san gad dèyè.", bookId = 25),
        Verse(book = "Lamantasyon", chapter = 2, verseNumber = 22, text = "Ou fè moun k'ap fè m' pè yo soti toupatou pou yo vin danse, fè fèt sou do m'. Lè Seyè a move, pesonn pa ka chape, tout moun gen pou mouri. Lènmi m' yo touye ata timoun mwen te renmen yo, timoun mwen te elve yo. Plenn", bookId = 25),
        Verse(book = "Lamantasyon", chapter = 3, verseNumber = 1, text = "Mwen se yon nonm ki konnen mizè moun gen pou pase lè Bondye ankòlè sou yo, lè Bondye ap pini yo.", bookId = 25),
        Verse(book = "Lamantasyon", chapter = 3, verseNumber = 2, text = "Li trennen m', li fè m' mache nan fènwa san yon ti limyè pou klere m'.", bookId = 25),
        Verse(book = "Lamantasyon", chapter = 3, verseNumber = 3, text = "Tout lajounen, l'ap plede bat mwen san rete.", bookId = 25),
        Verse(book = "Lamantasyon", chapter = 3, verseNumber = 4, text = "Po kò m' fin chire, vyann mwen parèt deyò konsa. Li kraze tout zo nan kò m'.", bookId = 25),
        Verse(book = "Lamantasyon", chapter = 3, verseNumber = 5, text = "Li fèmen m' nan yon koridò mizè ak lafliksyon.", bookId = 25),
        Verse(book = "Lamantasyon", chapter = 3, verseNumber = 6, text = "Li fè m' rete kote ki fènwa a tankou moun mouri yo.", bookId = 25),
        Verse(book = "Lamantasyon", chapter = 3, verseNumber = 7, text = "Li moute yon miray, li fèmen kote m' ye a, m' pa ka chape. Li mare m' ak gwo chenn.", bookId = 25),
        Verse(book = "Lamantasyon", chapter = 3, verseNumber = 8, text = "Tout rele mwen rele byen fò, pesonn p'ap tande m'.", bookId = 25),
        Verse(book = "Lamantasyon", chapter = 3, verseNumber = 9, text = "Li simen gwo wòch toupatou sou wout mwen. Kote m' vire, chak pa mwen fè, m' bite.", bookId = 25),
        Verse(book = "Lamantasyon", chapter = 3, verseNumber = 10, text = "Tankou yon lous, li biske kò l', l'ap veye m'. Tankou yon lyon, li kache, l'ap tann mwen.", bookId = 25),
        Verse(book = "Lamantasyon", chapter = 3, verseNumber = 11, text = "Li fè m' tonbe nan bwa. Li filange tout kò m'. Lèfini, li lage m'.", bookId = 25),
        Verse(book = "Lamantasyon", chapter = 3, verseNumber = 12, text = "Li mete flèch nan banza li, li vize. Se sou mwen l'ap voye yo.", bookId = 25),
        Verse(book = "Lamantasyon", chapter = 3, verseNumber = 13, text = "Li fè flèch li yo antre fon nan kò m'.", bookId = 25),
        Verse(book = "Lamantasyon", chapter = 3, verseNumber = 14, text = "Tout moun nan peyi a ap pase m' nan betiz. Se toutan y'ap fè chante sou mwen.", bookId = 25),
        Verse(book = "Lamantasyon", chapter = 3, verseNumber = 15, text = "Li plen vant mwen ak manje anmè kou fyèl. Li fè m' bwè labsent jouk mwen sou.", bookId = 25),
        Verse(book = "Lamantasyon", chapter = 3, verseNumber = 16, text = "Li fwote tout figi m' atè, li fè m' kase dan m' nan wòch.", bookId = 25),
        Verse(book = "Lamantasyon", chapter = 3, verseNumber = 17, text = "Mwen pa konnen sa yo rele kè poze. Mwen bliye sa yo rele kè kontan.", bookId = 25),
        Verse(book = "Lamantasyon", chapter = 3, verseNumber = 18, text = "Mwen di: M' pa gen lontan pou m' viv ankò. M' pèdi tout espwa mwen te gen nan Bondye.", bookId = 25),
        Verse(book = "Lamantasyon", chapter = 3, verseNumber = 19, text = "Lè m' chonje nan ki mizè mwen ye, jan m'ap mache pwonmennen san rete, se tankou yon labsent, yon fyèl m'ap vale.", bookId = 25),
        Verse(book = "Lamantasyon", chapter = 3, verseNumber = 20, text = "Wi, lè m' chonje sa, kè m' sere, m' santi kè m' ap rache", bookId = 25),
        Verse(book = "Lamantasyon", chapter = 3, verseNumber = 21, text = "Men, mwen reprann kouraj lè m' chonje yon sèl bagay.", bookId = 25),
        Verse(book = "Lamantasyon", chapter = 3, verseNumber = 22, text = "Seyè a pa janm sispann renmen nou. L'ap toujou gen pitye pou nou.", bookId = 25),
        Verse(book = "Lamantasyon", chapter = 3, verseNumber = 23, text = "Tankou solèy la ki leve chak maten konsa tou l'ap toujou kenbe pawòl li.", bookId = 25),
        Verse(book = "Lamantasyon", chapter = 3, verseNumber = 24, text = "Mwen di: Se Seyè a ki tout mwen. Se nan li mwen mete tout espwa m'.", bookId = 25),
        Verse(book = "Lamantasyon", chapter = 3, verseNumber = 25, text = "Seyè a bon pou tout moun ki mete konfyans yo nan li, pou moun k'ap konte sou li.", bookId = 25),
        Verse(book = "Lamantasyon", chapter = 3, verseNumber = 26, text = "Sa bon pou nou rete dousman ap tann li vin delivre nou.", bookId = 25),
        Verse(book = "Lamantasyon", chapter = 3, verseNumber = 27, text = "Sa bon pou nou aprann sipòte depi nou tou jenn.", bookId = 25),
        Verse(book = "Lamantasyon", chapter = 3, verseNumber = 28, text = "Lè Bondye ap manyen ak nou, ann chita pou kont nou san di anyen.", bookId = 25),
        Verse(book = "Lamantasyon", chapter = 3, verseNumber = 29, text = "Nou pa bezwen plenyen. Nou pa janm konnen, ka gen espwa toujou.", bookId = 25),
        Verse(book = "Lamantasyon", chapter = 3, verseNumber = 30, text = "Se pou n' pare figi n' pou n' pran souflèt. Se pou n' asepte tou sa yo fè nou.", bookId = 25),
        Verse(book = "Lamantasyon", chapter = 3, verseNumber = 31, text = "Bondye sèl Mèt la p'ap janm lage nou nèt.", bookId = 25),
        Verse(book = "Lamantasyon", chapter = 3, verseNumber = 32, text = "Li ka fè nou lapenn, men l'ap gen pitye pou nou paske li renmen nou anpil.", bookId = 25),
        Verse(book = "Lamantasyon", chapter = 3, verseNumber = 33, text = "Li pa pran plezi nan fè nou soufri, ni nan ban nou lapenn.", bookId = 25),
        Verse(book = "Lamantasyon", chapter = 3, verseNumber = 34, text = "Atò, se konnen Seyè a, Bondye sèl Mèt la, pa konnen lè y'ap kraze prizonye anba baton,", bookId = 25),
        Verse(book = "Lamantasyon", chapter = 3, verseNumber = 35, text = "lè yo derefize rekonèt dwa Bondye ban nou,", bookId = 25),
        Verse(book = "Lamantasyon", chapter = 3, verseNumber = 36, text = "lè y'ap bay move jijman nan tribinal! Atò, se konnen li pa konnen!", bookId = 25),
        Verse(book = "Lamantasyon", chapter = 3, verseNumber = 37, text = "Depi Bondye Sèl Mèt la pale, se fini! Sa l' di se sak fèt.", bookId = 25),
        Verse(book = "Lamantasyon", chapter = 3, verseNumber = 38, text = "Tou sa ki rive an byen osinon an mal, se li menm ki penmèt sa.", bookId = 25),
        Verse(book = "Lamantasyon", chapter = 3, verseNumber = 39, text = "Lè nou anba bwa pou peche nou yo sa nou bezwen plenyen fè!", bookId = 25),
        Verse(book = "Lamantasyon", chapter = 3, verseNumber = 40, text = "Annou gade jan n'ap mennen bak nou! Ann egzaminen byen jan n'ap viv la! Lèfini, ann tounen vin jwenn Bondye!", bookId = 25),
        Verse(book = "Lamantasyon", chapter = 3, verseNumber = 41, text = "Ann leve bra nou nan syèl la, ann lapriyè nan pye l'!", bookId = 25),
        Verse(book = "Lamantasyon", chapter = 3, verseNumber = 42, text = "Nou peche, nou kenbe tèt avè ou! Men, ou menm ou pa padonnen nou.", bookId = 25),
        Verse(book = "Lamantasyon", chapter = 3, verseNumber = 43, text = "Ou move pi rèd, ou fann nan kò nou! Ou te san pitye. Ou touye nou.", bookId = 25),
        Verse(book = "Lamantasyon", chapter = 3, verseNumber = 44, text = "Ou vlope kò ou nan yon gwo nwaj nwa pou lapriyè nou pa rive nan zòrèy ou.", bookId = 25),
        Verse(book = "Lamantasyon", chapter = 3, verseNumber = 45, text = "Ou fè nou tounen yon depotwa, yon pil fatra nan mitan lòt nasyon sou latè yo.", bookId = 25),
        Verse(book = "Lamantasyon", chapter = 3, verseNumber = 46, text = "Tout lènmi nou yo ap lave bouch yo sou nou.", bookId = 25),
        Verse(book = "Lamantasyon", chapter = 3, verseNumber = 47, text = "N'ap viv ak kè sote, si se pa lanmò, se gwo danje, se gwo malè!", bookId = 25),
        Verse(book = "Lamantasyon", chapter = 3, verseNumber = 48, text = "De je m' yo ap ponpe dlo tankou larivyè, lè m' wè malè ki tonbe sou pèp mwen an!", bookId = 25),
        Verse(book = "Lamantasyon", chapter = 3, verseNumber = 49, text = "Dlo ap koule nan je m' san rete. Li p'ap janm sispann,", bookId = 25),
        Verse(book = "Lamantasyon", chapter = 3, verseNumber = 50, text = "jouk jou Seyè a va rete nan syèl la, l'a voye je l' gade, l'a wè!", bookId = 25),
        Verse(book = "Lamantasyon", chapter = 3, verseNumber = 51, text = "Wi, kè m' fè m' mal pou m' wè sa ki rive moun lavil mwen yo!", bookId = 25),
        Verse(book = "Lamantasyon", chapter = 3, verseNumber = 52, text = "Yon bann moun ki pa vle wè m' san m' pa fè yo anyen pran kouri dèyè m' tankou yon zwazo y'ap chache pran.", bookId = 25),
        Verse(book = "Lamantasyon", chapter = 3, verseNumber = 53, text = "Yo lage m' tou vivan nan yon twou. Yo fèmen bouch twou a ak wòch.", bookId = 25),
        Verse(book = "Lamantasyon", chapter = 3, verseNumber = 54, text = "Dlo te prèt pou kouvri tèt mwen. Mwen di: Fwa sa a m' pran!", bookId = 25),
        Verse(book = "Lamantasyon", chapter = 3, verseNumber = 55, text = "Nan twou kote m' te ye a, Seyè, mwen rele ou!", bookId = 25),
        Verse(book = "Lamantasyon", chapter = 3, verseNumber = 56, text = "Ou tande vwa m'. Tanpri, pa bouche zòrèy ou lè m'ap lapriyè nan pye ou.", bookId = 25),
        Verse(book = "Lamantasyon", chapter = 3, verseNumber = 57, text = "Wi, lè m' rele ou, ou pwoche. Ou di m' mwen pa bezwen pè!", bookId = 25),
        Verse(book = "Lamantasyon", chapter = 3, verseNumber = 58, text = "Bondye Sèl Mèt, ou pran ka m' an konsiderasyon. Ou sove lavi m'.", bookId = 25),
        Verse(book = "Lamantasyon", chapter = 3, verseNumber = 59, text = "Seyè, ou wè tout lenjistis y'ap fè m'. Tanpri, defann kòz mwen.", bookId = 25),
        Verse(book = "Lamantasyon", chapter = 3, verseNumber = 60, text = "Ou wè jan yo soti pou pwofite sou mwen, jan y'ap fè konplo pou touye m'.", bookId = 25),
        Verse(book = "Lamantasyon", chapter = 3, verseNumber = 61, text = "Seyè, ou tande jan y'ap joure m'. Ou konnen konplo y'ap fè sou do m'.", bookId = 25),
        Verse(book = "Lamantasyon", chapter = 3, verseNumber = 62, text = "Tout lajounen, y'ap pale sou mwen, y'ap fè plan.", bookId = 25),
        Verse(book = "Lamantasyon", chapter = 3, verseNumber = 63, text = "Gade yo non! Depi maten jouk aswè yo chita ap fè chante sou do m'!", bookId = 25),
        Verse(book = "Lamantasyon", chapter = 3, verseNumber = 64, text = "Seyè, se pou ou pini yo pou tou sa yo fè.", bookId = 25),
        Verse(book = "Lamantasyon", chapter = 3, verseNumber = 65, text = "Madichonnen yo! Fè yo pèdi tèt yo!", bookId = 25),
        Verse(book = "Lamantasyon", chapter = 3, verseNumber = 66, text = "Move sou yo, Seyè! Pati dèyè yo! Disparèt yo sou latè! Plenn", bookId = 25),
        Verse(book = "Lamantasyon", chapter = 4, verseNumber = 1, text = "Gade jan bon lò pa klere ankò! Li chanje, li pèdi kalite li! Gade jan wòch Tanp yo gaye nan tout lari!", bookId = 25),
        Verse(book = "Lamantasyon", chapter = 4, verseNumber = 2, text = "Nan tan lontan nou pa ta bay moun peyi Siyon yo pou pi bon lò ki genyen. Gade! Koulye a, yo pa vo pase krich tè moun fè ak men.", bookId = 25),
        Verse(book = "Lamantasyon", chapter = 4, verseNumber = 3, text = "Ata manman chat mawon bay pitit yo tete. Men, pèp mwen an mechan tankou otrich k'ap viv nan dezè. Yo pa pran swen pitit yo.", bookId = 25),
        Verse(book = "Lamantasyon", chapter = 4, verseNumber = 4, text = "Lang ti bebe yo kole nan fon bouch yo sitèlman yo swaf dlo. Timoun yo ap rele mande manje. Pa gen pesonn pou ba yo anyen!", bookId = 25),
        Verse(book = "Lamantasyon", chapter = 4, verseNumber = 5, text = "Moun ki te konn manje bon manje gou ap tonbe faya nan lari. Moun ki te elve nan gran kay ap chache manje nan fatra.", bookId = 25),
        Verse(book = "Lamantasyon", chapter = 4, verseNumber = 6, text = "Peche lavil Jerizalèm pi gwo pase peche lavil Sodòm, ki te rete konsa Bondye disparèt li.", bookId = 25),
        Verse(book = "Lamantasyon", chapter = 4, verseNumber = 7, text = "Nazirit nou yo te san repwòch. Pi bon pase yo pa t' genyen. Yo te anfòm, yo te gwonèg. Yon bèl san wouj t'ap koule nan venn yo!", bookId = 25),
        Verse(book = "Lamantasyon", chapter = 4, verseNumber = 8, text = "Koulye a, se lonbraj yo ase ki la. Yo fini. Pesonn pa rekonèt yo nan lari. Po yo chèch tankou kòs bwa, yo tounen zo ak po.", bookId = 25),
        Verse(book = "Lamantasyon", chapter = 4, verseNumber = 9, text = "Moun ki mouri nan lagè pi bon pase moun ki mouri grangou. Y'ap depafini jouk yo mouri. Yo pa jwenn anyen pou yo manje.", bookId = 25),
        Verse(book = "Lamantasyon", chapter = 4, verseNumber = 10, text = "Manman ki te renmen pitit yo anpil, koulye a, yo kwit yo pou yo manje. Lè malè a tonbe sou pèp mwen an, se sa yo fè pou yo pa mouri grangou.", bookId = 25),
        Verse(book = "Lamantasyon", chapter = 4, verseNumber = 11, text = "Seyè a fache nèt. Li limen yon sèl kalite dife nan lavil Siyon. Li boule l' ratè.", bookId = 25),
        Verse(book = "Lamantasyon", chapter = 4, verseNumber = 12, text = "Pesonn sou latè, pa menm wa peyi sou latè yo, pa t' vle kwè yon jou, moun ki pa vle wè pèp Bondye a ta antre nan pòtay lavil Jerizalèm!", bookId = 25),
        Verse(book = "Lamantasyon", chapter = 4, verseNumber = 13, text = "Men, tou sa rive paske pwofèt li yo ak prèt li yo te peche. Yo te lakòz anpil moun ki mache dwat pèdi lavi yo mal.", bookId = 25),
        Verse(book = "Lamantasyon", chapter = 4, verseNumber = 14, text = "Y'ap mache nan lari tankou moun avèg. Yo bade ak san. Pesonn pa gen dwa manyen rad yo.", bookId = 25),
        Verse(book = "Lamantasyon", chapter = 4, verseNumber = 15, text = "Kote yo pase moun ap rele: Wete kò nou la! Nou pa pwòp! Pa pwoche! Pa manyen m'! Se konsa y'ap plede kouri sot nan yon peyi al nan yon lòt. Pesonn pa vle resevwa yo.", bookId = 25),
        Verse(book = "Lamantasyon", chapter = 4, verseNumber = 16, text = "Seyè a pa vle wè yo ankò, se li menm ki gaye yo konsa. Li pa gen konsiderasyon ni pou pè yo ni pou chèf yo.", bookId = 25),
        Verse(book = "Lamantasyon", chapter = 4, verseNumber = 17, text = "Je nou wouj afòs nou kriye. N'ap tann yon sekou ki pa janm vini. M'ap veye tann yon nasyon ki pa ka fè anyen pou delivre nou.", bookId = 25),
        Verse(book = "Lamantasyon", chapter = 4, verseNumber = 18, text = "Lènmi ap veye kote nou prale. Nou pa menm gen dwa soti nan lari. Jou lanmò nou rive. Sa ki rete pou nou mouri a pa anyen.", bookId = 25),
        Verse(book = "Lamantasyon", chapter = 4, verseNumber = 19, text = "Moun ki t'ap kouri dèyè nou yo te pi rapid pase malfini k'ap plonje dèyè poul. Y'ap kouri dèyè nou nan tout mòn yo. Yo tann pèlen pou nou nan tout dezè a.", bookId = 25),
        Verse(book = "Lamantasyon", chapter = 4, verseNumber = 20, text = "Moun Seyè a te chwazi a, li menm ki tout souf lavi nou, li menm nou te konprann ki ta ka toujou pwoteje nou pou lòt nasyon pa anvayi nou, yo pran l', yo mete l' nan prizon!", bookId = 25),
        Verse(book = "Lamantasyon", chapter = 4, verseNumber = 21, text = "Nou menm, moun peyi Edon ki rete lavil Ouz, nou mèt fè kè nou kontan, nou mèt fè fèt! Tou pa nou dèyè, tande! Jou sa a, nou pral titibe toutouni nan tout lari.", bookId = 25),
        Verse(book = "Lamantasyon", chapter = 4, verseNumber = 22, text = "Nou menm, moun lavil Siyon, nou fin peye pou peche nou yo. Bondye ap sispann pini nou! Men, nou menm moun Edon, Seyè a pral pini nou pou peche nou yo. L'ap denonse tou sa nou fè ki mal. Plenn", bookId = 25),
        Verse(book = "Lamantasyon", chapter = 5, verseNumber = 1, text = "Seyè, gade sa ki te rive nou non! Voye je gade nou. Wè nan ki mizè nou ye!", bookId = 25),
        Verse(book = "Lamantasyon", chapter = 5, verseNumber = 2, text = "Peyi nou an nan men moun lòt nasyon! Yo pran kay nou pou yo.", bookId = 25),
        Verse(book = "Lamantasyon", chapter = 5, verseNumber = 3, text = "Nou se timoun san papa. Manman nou tankou fanm ki pèdi mari yo.", bookId = 25),
        Verse(book = "Lamantasyon", chapter = 5, verseNumber = 4, text = "Se achte pou n' achte dlo pou nou bwè. Si nou pa gen lajan, nou pa jwenn bwa pou nou boule.", bookId = 25),
        Verse(book = "Lamantasyon", chapter = 5, verseNumber = 5, text = "N'ap travay di tankou bourik, tankou bèf kabwa. Nou bouke, nou pa ka pran kanpo.", bookId = 25),
        Verse(book = "Lamantasyon", chapter = 5, verseNumber = 6, text = "Pou nou ka jwenn manje pou nou manje nou blije ap lonje men bay peyi Lejip ak peyi Lasiri.", bookId = 25),
        Verse(book = "Lamantasyon", chapter = 5, verseNumber = 7, text = "Zansèt nou yo fè peche. Yo pa la ankò! Se nou menm k'ap peye pou sa yo te fè.", bookId = 25),
        Verse(book = "Lamantasyon", chapter = 5, verseNumber = 8, text = "Moun k'ap gouvènen nou yo se esklav yo ye. Pesonn pa ka delivre nou anba men yo.", bookId = 25),
        Verse(book = "Lamantasyon", chapter = 5, verseNumber = 9, text = "Se gwo danje lè nou soti al dèyè manje. Ansasen toupatou nan peyi a.", bookId = 25),
        Verse(book = "Lamantasyon", chapter = 5, verseNumber = 10, text = "Grangou ban nou lafyèb. Kò nou cho kou dife.", bookId = 25),
        Verse(book = "Lamantasyon", chapter = 5, verseNumber = 11, text = "Yo fè kadejak sou madanm nou sou mòn Siyon an. Nan tout ti bouk peyi Jida yo yo kenbe pitit fi nou yo.", bookId = 25),
        Verse(book = "Lamantasyon", chapter = 5, verseNumber = 12, text = "Yo pran chèf nou yo, yo pann yo. Yo derespekte granmoun nou yo.", bookId = 25),
        Verse(book = "Lamantasyon", chapter = 5, verseNumber = 13, text = "Yo fòse jenn gason nou yo rale moulen. Ti gason nou yo ap titibe anba gwo chay bwa.", bookId = 25),
        Verse(book = "Lamantasyon", chapter = 5, verseNumber = 14, text = "Granmoun yo pa chita nan pòtay lavil la ankò. Jennmoun nou yo pa chante ankò.", bookId = 25),
        Verse(book = "Lamantasyon", chapter = 5, verseNumber = 15, text = "Pa gen kè kontan lakay nou. Nou pa danse ankò! Lapenn plen kè nou!", bookId = 25),
        Verse(book = "Lamantasyon", chapter = 5, verseNumber = 16, text = "Tou sa ki te konn ban nou kè kontan disparèt. Nou te peche, malè tonbe sou nou.", bookId = 25),
        Verse(book = "Lamantasyon", chapter = 5, verseNumber = 17, text = "Nou malad nan fon kè nou, nou pa ka wè tèlman n'ap kriye,", bookId = 25),
        Verse(book = "Lamantasyon", chapter = 5, verseNumber = 18, text = "paske mòn Siyon an tounen savann. Se bèt nan bwa ase ki rete la.", bookId = 25),
        Verse(book = "Lamantasyon", chapter = 5, verseNumber = 19, text = "Men ou menm, Seyè, ou wa pou tou tan. W'ap gouvènen jouk sa kaba.", bookId = 25),
        Verse(book = "Lamantasyon", chapter = 5, verseNumber = 20, text = "Poukisa ou lage nou pou tout tan sa a? Gen lè ou p'ap janm chonje nou ankò!", bookId = 25),
        Verse(book = "Lamantasyon", chapter = 5, verseNumber = 21, text = "Seyè, fè nou tounen vin jwenn ou non! Fè nou tounen vin jwenn ou! Fè nou viv jan nou te konn viv nan tan lontan an non!", bookId = 25),
        Verse(book = "Lamantasyon", chapter = 5, verseNumber = 22, text = "Eske ou voye nou jete pou tout bon? Pou di ou p'ap janm sispann fache sou nou? Plenn", bookId = 25)
    )
}

